use super::IconSetType;

// Microsoft Office fixed-output PDFs for Apache POI's
// NewStyleConditionalFormattings.xlsx and ConditionalFormattingSamples.xlsx
// expose the standard 24x24 icon artwork as image/SMask pairs. The object
// sharing below also agrees with LibreOffice colorscale.cxx (for example,
// FourRating is a subset of FiveRating and the gray arrow sets share states).
// Keep one decoded PNG for each unique Office object instead of approximating
// producer-defined artwork with paths.
pub(super) fn office_icon_base64(icon_set: IconSetType, icon_index: usize) -> Option<&'static str> {
  let object = match icon_set {
    IconSetType::ThreeTrafficLights1 => [41, 59, 79].get(icon_index),
    IconSetType::ThreeSigns => [43, 61, 79].get(icon_index),
    IconSetType::ThreeTrafficLights2 => [45, 63, 81].get(icon_index),
    IconSetType::FourTrafficLights => [47, 41, 59, 79].get(icon_index),
    IconSetType::ThreeSymbols => [49, 65, 83].get(icon_index),
    IconSetType::ThreeFlags => [51, 67, 85].get(icon_index),
    IconSetType::ThreeSymbols2 => [53, 69, 87].get(icon_index),
    IconSetType::ThreeArrows => [55, 71, 89].get(icon_index),
    IconSetType::ThreeArrowsGray => [57, 75, 91].get(icon_index),
    IconSetType::FourArrowsGray => [57, 73, 77, 91].get(icon_index),
    IconSetType::FiveArrowsGray => [57, 73, 75, 77, 91].get(icon_index),
    IconSetType::ThreeStars => [95, 101, 107].get(icon_index),
    IconSetType::FourRating => [97, 103, 105, 109].get(icon_index),
    IconSetType::FiveRating => [99, 97, 103, 105, 109].get(icon_index),
    IconSetType::FiveQuarters => [148, 146, 144, 142, 140].get(icon_index),
    _ => None,
  }?;
  object_base64(*object)
}

